/**
 * EST Phase 1 (docs/est/EST_Phase1_Work_Order.md §1.1): typed accessors over a `DataView` for the
 * pinned CLAP 1.2 wasm32 structs, read from `est-abi-1.0.json` (generated by `scripts/est-abi.mjs`
 * from the vendored headers; never typed by hand). Struct and field names are checked by the
 * compiler against the JSON, so a field the table does not hold is a type error.
 *
 * The worklet cannot import this file (its processor is serialised: CLAUDE.md, "Worklets are
 * serialised to a Blob"): it gets `compactAbi()`, the same offsets as a plain object literal
 * injected into its source.
 */

// EST 1.1 (1.327, DEV-H, D-56): the host reads the 1.1 table, a superset of 1.0's with every 1.0
// struct, constant and string unchanged (scripts/est-abi.test.mjs), so a 1.0 bundle sees its own.
import abi from './est-abi-1.1.json';

export const ABI = abi;
export type Abi = typeof abi;
export type StructName = keyof Abi['structs'];
export type FieldName<S extends StructName> = keyof Abi['structs'][S]['fields'] & string;
export type ConstantName = keyof Abi['constants'];
export type StringName = keyof Abi['strings'];

interface FieldInfo { offset: number; size: number; kind: string; elem?: string; count?: number; sig?: string; ctype: string }
interface StructInfo { size: number; align: number; fields: Record<string, FieldInfo> }

function struct(s: StructName): StructInfo {
  return abi.structs[s] as unknown as StructInfo;
}

function field<S extends StructName>(s: S, f: FieldName<S>): FieldInfo {
  const info = struct(s).fields[f];
  if (!info) throw new Error(`${s} has no field ${f}`);
  return info;
}

export const sizeOf = (s: StructName): number => struct(s).size;
export const alignOf = (s: StructName): number => struct(s).align;
export const offsetOf = <S extends StructName>(s: S, f: FieldName<S>): number => field(s, f).offset;
export const kindOf = <S extends StructName>(s: S, f: FieldName<S>): string => field(s, f).kind;
export const constant = (c: ConstantName): number => abi.constants[c];
export const idString = (s: StringName): string => abi.strings[s];

/** The scalar kinds a field may have (`array` and `struct:…` are read through their own helpers). */
const SCALAR_KINDS = new Set(['bool', 'char', 'i8', 'u8', 'i16', 'u16', 'i32', 'u32', 'ptr', 'fnptr', 'f32', 'f64', 'i64', 'u64']);

/** Read a scalar field of the struct at `base` (64-bit integers as `bigint`, the rest as numbers). */
export function readField<S extends StructName>(view: DataView, base: number, s: S, f: FieldName<S>): number | bigint {
  const { offset, kind } = field(s, f);
  const at = base + offset;
  switch (kind) {
    case 'bool': case 'u8': case 'char': return view.getUint8(at);
    case 'i8': return view.getInt8(at);
    case 'u16': return view.getUint16(at, true);
    case 'i16': return view.getInt16(at, true);
    case 'u32': case 'ptr': case 'fnptr': return view.getUint32(at, true);
    case 'i32': return view.getInt32(at, true);
    case 'f32': return view.getFloat32(at, true);
    case 'f64': return view.getFloat64(at, true);
    case 'i64': return view.getBigInt64(at, true);
    case 'u64': return view.getBigUint64(at, true);
    default: throw new Error(`${s}.${f} is a ${kind}, not a scalar`);
  }
}

/** A scalar field read as a number (64-bit integers converted; for pointers, counts and flags). */
export function readNumber<S extends StructName>(view: DataView, base: number, s: S, f: FieldName<S>): number {
  return Number(readField(view, base, s, f));
}

/** Write a scalar field (a `bigint` or a number for the 64-bit kinds). */
export function writeField<S extends StructName>(view: DataView, base: number, s: S, f: FieldName<S>, v: number | bigint | boolean): void {
  const { offset, kind } = field(s, f);
  const at = base + offset;
  const n = typeof v === 'boolean' ? (v ? 1 : 0) : v;
  switch (kind) {
    case 'bool': case 'u8': case 'char': view.setUint8(at, Number(n)); return;
    case 'i8': view.setInt8(at, Number(n)); return;
    case 'u16': view.setUint16(at, Number(n), true); return;
    case 'i16': view.setInt16(at, Number(n), true); return;
    case 'u32': case 'ptr': case 'fnptr': view.setUint32(at, Number(n), true); return;
    case 'i32': view.setInt32(at, Number(n), true); return;
    case 'f32': view.setFloat32(at, Number(n), true); return;
    case 'f64': view.setFloat64(at, Number(n), true); return;
    case 'i64': view.setBigInt64(at, BigInt(n), true); return;
    case 'u64': view.setBigUint64(at, BigInt(n), true); return;
    default: throw new Error(`${s}.${f} is a ${kind}, not a scalar`);
  }
}

/** A NUL-terminated string in memory (ASCII/UTF-8 bytes read as Latin-1: ids and names). */
export function readCString(view: DataView, ptr: number, max = 4096): string {
  let s = '';
  for (let i = 0; i < max && ptr + i < view.byteLength; i++) {
    const b = view.getUint8(ptr + i);
    if (!b) break;
    s += String.fromCharCode(b);
  }
  return s;
}

/** A `char name[N]` field as a string. */
export function readCharArray<S extends StructName>(view: DataView, base: number, s: S, f: FieldName<S>): string {
  const info = field(s, f);
  if (info.kind !== 'array' || info.elem !== 'char') throw new Error(`${s}.${f} is not a char array`);
  return readCString(view, base + info.offset, info.size);
}

/** Write a string into a `char name[N]` field, truncated to N - 1 bytes and NUL-terminated. */
export function writeCharArray<S extends StructName>(view: DataView, base: number, s: S, f: FieldName<S>, text: string): void {
  const info = field(s, f);
  if (info.kind !== 'array' || info.elem !== 'char') throw new Error(`${s}.${f} is not a char array`);
  const n = Math.min(text.length, info.size - 1);
  for (let i = 0; i < n; i++) view.setUint8(base + info.offset + i, text.charCodeAt(i) & 0xff);
  view.setUint8(base + info.offset + n, 0);
}

/** Whether a field is a scalar `readField` and `writeField` take. */
export const isScalar = <S extends StructName>(s: S, f: FieldName<S>): boolean => SCALAR_KINDS.has(field(s, f).kind);

/** Every function pointer of a struct with its Wasm signature, in declaration order. */
export function fnFields<S extends StructName>(s: S): { name: FieldName<S>; offset: number; sig: string }[] {
  return Object.entries(struct(s).fields)
    .filter(([, f]) => f.kind === 'fnptr')
    .map(([name, f]) => ({ name: name as FieldName<S>, offset: f.offset, sig: f.sig ?? '' }));
}

/** The worklet's copy of the table: per struct `$size` and each field's offset; the constants; the id strings. */
export type CompactAbi = {
  s: { [S in StructName]: { $size: number } & { [F in FieldName<S>]: number } };
  c: Abi['constants'];
  str: Abi['strings'];
  /** The host-side callbacks' Wasm signatures, `struct.field` → `(i32)->void`. */
  sig: Record<string, string>;
};

/** The structs whose function pointers the host implements (the shim exports one function for each). */
export const HOST_STRUCTS = [
  'clap_host', 'clap_input_events', 'clap_output_events', 'clap_host_params', 'clap_host_state', 'clap_host_latency',
  'clap_host_tail', 'clap_host_log', 'clap_host_thread_check', 'clap_host_audio_ports', 'clap_host_note_ports',
  'clap_istream', 'clap_ostream',
] as const satisfies readonly StructName[];

export function compactAbi(): CompactAbi {
  const s = {} as Record<string, Record<string, number>>;
  for (const [name, info] of Object.entries(abi.structs) as [string, StructInfo][]) {
    const row: Record<string, number> = { $size: info.size };
    for (const [f, fi] of Object.entries(info.fields)) row[f] = fi.offset;
    s[name] = row;
  }
  const sig: Record<string, string> = {};
  for (const h of HOST_STRUCTS) for (const f of fnFields(h)) sig[`${h}.${f.name}`] = f.sig;
  return { s: s as CompactAbi['s'], c: abi.constants, str: abi.strings, sig };
}
